import type {TrafficData} from '../hooks/use-traffic-data'

export interface ChartDataPoint {
  name: string
  data: number[]
}

export interface TrafficChartData {
  chartData: ChartDataPoint[]
  categories: string[]
  maxValue: number // Maximum value for y-axis
  summary: {
    total: number
    unique: number
  }
  dateRangeHeader?: string // Added for displaying the date range in the header
}

/**
 * Creates a formatted date range header in the format "Month Day, Year — Month Day, Year"
 */
export function createDateRangeHeader(data: TrafficData): string {
  if (!data || !data.counts || data.counts.length === 0) {
    return ''
  }

  const sortedDates = [...data.counts].map(count => count.date).sort((a, b) => a.getTime() - b.getTime())

  // We know these dates exist since we checked data.counts.length > 0
  const firstDate = sortedDates[0]
  const lastDate = sortedDates[sortedDates.length - 1]

  const formatDate = (date: Date | undefined): string => {
    if (!date) return ''
    return date.toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    })
  }

  return `${formatDate(firstDate)} — ${formatDate(lastDate)}`
}

/**
 * Transforms backend traffic data into format expected by TrafficGraph component
 */
export function transformTrafficData(
  data: TrafficData,
  options: {
    includeTotal?: boolean
    includeUnique?: boolean
    dateFormat?: 'short' | 'long'
    period?: string // Add period to determine time granularity
  } = {},
): TrafficChartData {
  const {includeTotal = true, includeUnique = true, dateFormat = 'short', period} = options // Default options
  // Handle empty or invalid data
  if (!data || !data.counts || data.counts.length === 0) {
    return {
      chartData: [],
      categories: [],
      maxValue: 0,
      summary: {total: 0, unique: 0},
    }
  }

  // Sort counts by date to ensure proper order
  const sortedCounts = [...data.counts].sort((a, b) => a.date.getTime() - b.date.getTime())

  // Generate categories (date labels) - handle different time granularities
  let isHourlyData = false
  if (period === 'day' && sortedCounts.length > 1) {
    // Calculate the minimum time difference between consecutive data points
    let minDiff = Infinity
    for (let i = 1; i < sortedCounts.length; i++) {
      const prev = sortedCounts[i - 1]
      const curr = sortedCounts[i]
      if (prev && curr && prev.date && curr.date) {
        const diff = curr.date.getTime() - prev.date.getTime()
        if (diff > 0 && diff < minDiff) {
          minDiff = diff
        }
      }
    }
    isHourlyData = minDiff > 0 && minDiff <= 3600000 // 1 hour in milliseconds
  }

  const categories = sortedCounts.map(count => {
    if (isHourlyData) {
      // Format as MM/DD HH:00 for hourly data
      const month = String(count.date.getUTCMonth() + 1).padStart(2, '0')
      const day = String(count.date.getUTCDate()).padStart(2, '0')
      const hour = String(count.date.getHours()).padStart(2, '0')
      return `${month}/${day} ${hour}:00`
    }

    // Default formatting for daily/weekly data
    if (dateFormat === 'short') {
      // Format as MM/DD - directly extract month and day
      const month = String(count.date.getUTCMonth() + 1).padStart(2, '0')
      const day = String(count.date.getUTCDate()).padStart(2, '0')
      return `${month}/${day}`
    } else {
      return count.date.toLocaleDateString('en-US', {
        weekday: 'short',
        month: 'short',
        day: 'numeric',
      })
    }
  })

  // Build chart data series
  const chartData: ChartDataPoint[] = []

  if (includeTotal) {
    chartData.push({
      name: 'Total',
      data: sortedCounts.map(count => count.total),
    })
  }

  if (includeUnique) {
    chartData.push({
      name: 'Unique',
      data: sortedCounts.map(count => count.unique),
    })
  }

  // Calculate max value for y-axis
  const allValues = chartData.flatMap(series => series.data)
  const maxValue = Math.max(...allValues, 0)

  return {
    chartData,
    categories,
    maxValue,
    summary: data.summary,
    dateRangeHeader: createDateRangeHeader(data),
  }
}

/**
 * Transform data specifically for visitors graph
 */
export function transformVisitorsData(data: TrafficData): TrafficChartData {
  return transformTrafficData(data, {
    includeTotal: true,
    includeUnique: true,
    dateFormat: 'short',
    period: 'week', // Default to weekly data
  })
}

/**
 * Transform data specifically for clones graph
 */
export function transformClonesData(data: TrafficData): TrafficChartData {
  return transformTrafficData(data, {
    includeTotal: true,
    includeUnique: false, // Only show total clones to match design
    dateFormat: 'short',
    period: 'week', // Default to weekly data
  })
}
