import {Banner, Heading} from '@primer/react'
import {ReferringSitesTable} from '../components/tables/ReferringSitesTable'
import {ReferringPathsTable} from '../components/tables/ReferringPathsTable'
import {PopularContentTable} from '../components/tables/PopularContentTable'
import {useTrafficChart} from '../hooks/use-traffic-chart'
import {RealTrafficGraph} from '../components/RealTrafficGraph'
import {TrafficError} from '../components/TrafficError'
import {useRepoContext} from '../hooks/use-repo-context'
import {useSearchParams} from '@github-ui/react-router'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export function Traffic() {
  const {owner, repo} = useRepoContext()
  const newTrafficPageBanner = isFeatureEnabled('new_traffic_page_banner')

  const [searchParams] = useSearchParams()
  const selectedReferrer = searchParams.get('referrer')

  const {
    chartData: _trafficData,
    isLoading: _isLoading,
    error,
  } = useTrafficChart({
    dataUrl: `/${owner}/${repo}/graphs/traffic-new/traffic`,
    per: 'week',
    enabled: true,
  })

  const commonChartProps = {
    per: 'week' as const,
  }

  const cloneDataUrl = `/${owner}/${repo}/graphs/traffic-new/clone-activity`
  const trafficDataUrl = `/${owner}/${repo}/graphs/traffic-new/traffic`

  return (
    <div className="width-full">
      {newTrafficPageBanner && (
        <Banner
          variant="warning"
          hideTitle
          title="Referring sites and popular content are temporarily unavailable or may not display accurately."
          className="mb-3"
        >
          <Banner.Description>
            <p>
              Referring sites and popular content are temporarily unavailable or may not display accurately. We&apos;re
              actively working to resolve the issue.{' '}
              <span className="text-bold">
                Service restoration is expected to begin in early December and will roll out progressively over time.
              </span>
            </p>
          </Banner.Description>
        </Banner>
      )}

      {error && <TrafficError error={error} />}

      <Heading as="h2" className="f3 text-semibold mb-1 color-fg-default mt-3">
        Git clones
      </Heading>
      <div className="d-flex flex-wrap gap-4 mt-2">
        <RealTrafficGraph
          {...commonChartProps}
          title="Clones in last 14 days"
          dataUrl={cloneDataUrl}
          yAxisTitle="Clones"
          includeUnique={false}
        />
        <RealTrafficGraph
          {...commonChartProps}
          title="Unique cloners in last 14 days"
          dataUrl={cloneDataUrl}
          yAxisTitle="Cloners"
          includeTotal={false}
        />
      </div>

      <Heading as="h2" className="f3 text-semibold mb-1 color-fg-default mt-4">
        Visitors
      </Heading>
      <div className="d-flex flex-wrap gap-4 mt-2">
        <RealTrafficGraph
          {...commonChartProps}
          title="Total views in last 14 days"
          dataUrl={trafficDataUrl}
          yAxisTitle="Total views"
          includeUnique={false}
        />
        <RealTrafficGraph
          {...commonChartProps}
          title="Unique visitors in last 14 days"
          dataUrl={trafficDataUrl}
          yAxisTitle="Unique visitors"
          includeTotal={false}
        />
      </div>

      <div className="d-flex flex-wrap gap-4 mt-4">
        {selectedReferrer ? <ReferringPathsTable /> : <ReferringSitesTable />}
        <PopularContentTable />
      </div>
    </div>
  )
}

try{ Traffic.displayName ||= 'Traffic' } catch {}