import {TrafficDataTable, type TrafficDataItem} from '../TrafficDataTable'
import {Link, Truncate, Heading, Button} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {clsx} from 'clsx'
import {useSearchParams} from '@github-ui/react-router'
import styles from '../Traffic.module.css'

interface TrafficTableConfig {
  title: string
  emptyMessage: string
  ariaLabelledBy: string
  firstColumnHeader: string
  linkType?: 'site' | 'page' | 'path'
}

interface TrafficTableData {
  data: TrafficDataItem[] | null
  isLoading: boolean
  error: string | null
}

interface GenericTrafficTableProps {
  config: TrafficTableConfig
  trafficData: TrafficTableData
  selectedReferrer?: string | null
  onSelectReferrer?: (referrer: string) => void
  onClearReferrer?: () => void
}

export function GenericTrafficTable({
  config,
  trafficData,
  selectedReferrer,
  onSelectReferrer,
  onClearReferrer,
}: GenericTrafficTableProps) {
  const {data, isLoading, error} = trafficData
  const [searchParams] = useSearchParams()
  const referrer = searchParams.get('referrer')

  const hasData = Array.isArray(data) && data.length > 0 && data.some(item => item.views > 0 || item.uniqueVisitors > 0)

  // Create the title with clickable "Domains" link if we're showing referring paths
  const getTitle = () => {
    if (config.title === 'Referring paths' && selectedReferrer && onClearReferrer) {
      return (
        <>
          <Button variant="link" onClick={onClearReferrer}>
            Domains
          </Button>
          <span> / Referring sites</span>
        </>
      )
    }
    return config.title
  }

  const renderSiteCell = (item: TrafficDataItem) => {
    const siteValue = item.site
    // Make referring sites links to be clickable to filter the graph data
    if (config.linkType === 'site') {
      const display = siteValue || 'Unknown'
      const isSelected = !!selectedReferrer && selectedReferrer === display
      const buttonClass = clsx('btn-link', isSelected && 'selected')

      // Check if the referrer should not link to anything based on backend data
      const shouldNotLink = display === 'Unknown' || item.referrerPathsAllowed === false

      if (shouldNotLink) {
        return (
          <Truncate title={display} inline maxWidth="200px">
            {display}
          </Truncate>
        )
      }

      return (
        <Button
          variant="link"
          className={buttonClass}
          onClick={() => {
            if (!onSelectReferrer) return
            onSelectReferrer(display)
          }}
        >
          <Truncate title={display} inline maxWidth="200px">
            {display}
          </Truncate>
        </Button>
      )
    } else if (config.linkType === 'page') {
      // For popular content, use the path for linking but show the title
      const displayTitle = item.title || siteValue || 'Unknown'
      const linkPath = item.path || siteValue

      if (linkPath && linkPath !== 'Unknown' && !linkPath.includes('unknown-')) {
        return (
          <Link href={linkPath}>
            <Truncate title={displayTitle} maxWidth="200px" inline>
              {displayTitle}
            </Truncate>
          </Link>
        )
      }
      return (
        <Truncate title={displayTitle} maxWidth="200px" inline>
          {displayTitle}
        </Truncate>
      )
    } else if (config.linkType === 'path') {
      if (siteValue && siteValue !== 'Unknown' && !siteValue.includes('unknown-')) {
        const href = `https://${referrer}${siteValue}`
        return (
          <Link href={href}>
            <Truncate title={siteValue} maxWidth="200px" inline>
              {siteValue}
            </Truncate>
          </Link>
        )
      }
      return siteValue || 'Unknown'
    }

    const displayValue = siteValue || 'Unknown'
    return displayValue.length > 20 ? (
      <Truncate title={displayValue} maxWidth="200px" inline>
        {displayValue}
      </Truncate>
    ) : (
      displayValue
    )
  }

  if (!hasData) {
    return (
      <div className={clsx(styles.bottomSectionColumn, 'pb-6')}>
        <Heading as="h3" className="f3 text-semibold mb-1 color-fg-default" data-hpc>
          {getTitle()}
        </Heading>
        <div className="mt-3">
          <Blankslate border>
            <Blankslate.Heading as="h4" className="mb-2 f5">
              We don&apos;t have enough data to show anything useful.
            </Blankslate.Heading>
            <Blankslate.Description>It usually takes about a week to populate this table.</Blankslate.Description>
          </Blankslate>
        </div>
      </div>
    )
  }

  return (
    <div className={clsx(styles.bottomSectionColumn, 'pb-6')}>
      <TrafficDataTable
        title={getTitle()}
        data={data || []}
        isLoading={isLoading}
        error={error}
        columns={[
          {
            header: config.firstColumnHeader,
            field: 'site',
            rowHeader: true,
            renderCell: renderSiteCell,
          },
          {
            header: 'Views',
            field: 'views',
          },
          {
            header: 'Unique Visitors',
            field: 'uniqueVisitors',
          },
        ]}
        emptyMessage={config.emptyMessage}
        ariaLabelledBy={config.ariaLabelledBy}
      />
    </div>
  )
}

try{ GenericTrafficTable.displayName ||= 'GenericTrafficTable' } catch {}