import {useMemo} from 'react'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {transformReferringSites} from './traffic-utils'
import type {RawReferringSiteItem, SiteDataItem} from './traffic-types'

/**
 * Defines the input options for the hook
 */
interface UseReferringSitesOptions {
  dataUrl: string // The URL to fetch referring sites data from
  // Note: referring sites endpoint does not support period parameters
}

/**
 * Hook return type for referring sites data
 */
interface UseReferringSitesResult {
  data: SiteDataItem[] | null
  error?: string
  isLoading: boolean
}

/**
 * Hook that fetches referring sites data from a given URL and transforms it into a usable format.
 */
export function useReferringSites({dataUrl}: UseReferringSitesOptions): UseReferringSitesResult {
  // Referring sites endpoint does not support period parameters
  const fetchReferringSites = async (): Promise<RawReferringSiteItem[]> => {
    const response = await verifiedFetchJSON(dataUrl)

    if (!response.ok) {
      throw new Error(`Failed to fetch referring sites data: ${response.statusText}`)
    }

    return await response.json()
  }

  const {
    data: rawData,
    error: queryError,
    isLoading: queryIsLoading,
  } = useQuery({
    queryKey: ['referring-sites', dataUrl],
    queryFn: fetchReferringSites,
    refetchOnWindowFocus: false,
    staleTime: 60000, // 1 minute
    gcTime: 300000, // 5 minutes
  })

  const data = useMemo(() => {
    if (!rawData) return null
    return transformReferringSites(rawData)
  }, [rawData])

  return {
    data,
    error: queryError?.message,
    isLoading: queryIsLoading,
  }
}
