import {useMemo} from 'react'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {transformReferringPaths} from './traffic-utils'
import type {RawReferringPathItem, SiteDataItem} from './traffic-types'

/**
 * Defines the input options for the hook
 */
interface UseReferringPathsOptions {
  dataUrl: string // The URL to fetch referring paths data from
  referrer: string // The referrer domain to get paths for
}

/**
 * Hook return type for referring paths data
 */
interface UseReferringPathsResult {
  data: SiteDataItem[] | null
  error?: string
  isLoading: boolean
}

/**
 * Hook that fetches referring paths data for a specific referrer and transforms it into a usable format.
 */
export function useReferringPaths({dataUrl, referrer}: UseReferringPathsOptions): UseReferringPathsResult {
  const fetchReferringPaths = async (): Promise<RawReferringPathItem[]> => {
    const urlWithReferrer = `${dataUrl}?referrer=${encodeURIComponent(referrer)}`
    const response = await verifiedFetchJSON(urlWithReferrer)
    return await response.json()
  }

  const {
    data: rawData,
    error,
    isLoading,
  } = useQuery({
    queryKey: ['referring-paths', dataUrl, referrer],
    queryFn: fetchReferringPaths,
    enabled: Boolean(dataUrl && referrer),
  })

  const transformedData = useMemo(() => {
    if (!rawData) return null
    return transformReferringPaths(rawData)
  }, [rawData])

  return {
    data: transformedData,
    error: error?.message,
    isLoading,
  }
}
