import {useState, useEffect} from 'react'
import type {TrafficDataPoint, TrafficSummary} from './traffic-types'

/**
 * Legacy traffic data format returned by useTrafficData hook.
 *
 * @interface TrafficData
 * @property {string} [error] - Optional error message if data fetch failed
 * @property {TrafficSummary} summary - Summary statistics with total and unique counts
 * @property {TrafficDataPoint[]} counts - Array of traffic data points (legacy format)
 */
export interface TrafficData {
  error?: string
  summary: TrafficSummary
  counts: TrafficDataPoint[]
}

/**
 * Configuration options for the useTrafficData hook.
 *
 * @interface UseTrafficDataOptions
 * @property {string} dataUrl - The URL to fetch traffic data from
 * @property {boolean} [enabled] - Whether the hook should fetch data (default: true)
 * @property {string} [period] - The period for which to fetch data (e.g., 'day', 'week')
 */
interface UseTrafficDataOptions {
  dataUrl: string // The URL to fetch traffic data from
  enabled?: boolean // Whether the hook should fetch data
  period?: string // The period for which to fetch data (e.g., 'day', 'week')
}

/**
 * Structure of a single traffic record before transformation (dates still as timestamps)
 */
interface RawTrafficCount {
  bucket: number
  total: number
  unique: number
}

/**
 * Hook for fetching legacy traffic data format.
 *
 * @description This hook supports legacy endpoints that return data in the legacy format.
 * For modern endpoints, use `useClonesData` for clone traffic or `useViewsData` for view traffic.
 *
 * @param options - Configuration options for the hook
 * @param options.dataUrl - The URL to fetch traffic data from
 * @param options.enabled - Whether the hook should fetch data (default: true)
 * @param options.period - The period for which to fetch data (e.g., 'day', 'week')
 *
 * @returns An object containing:
 *   - `data`: Traffic data in legacy format `{summary: {total, unique}, counts: Array<{bucket, date, total, unique}>}`
 *   - `isLoading`: Boolean indicating if data is being fetched
 *   - `error`: Error message if fetch failed, null otherwise
 *
 * @example
 * ```typescript
 * const {data, isLoading, error} = useTrafficData({
 *   dataUrl: '/api/legacy-endpoint',
 *   enabled: true,
 *   period: 'day'
 * })
 * ```
 */
export function useTrafficData({dataUrl, enabled = true, period}: UseTrafficDataOptions) {
  const [data, setData] = useState<TrafficData | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!enabled || !dataUrl) {
      return
    }

    let isCancelled = false

    async function fetchData() {
      setIsLoading(true)
      setError(null)

      try {
        // Construct the URL with per parameter if provided (backend expects 'per', not 'period')
        const url = new URL(dataUrl, window.location.origin)
        if (period) {
          url.searchParams.set('per', period)
        }

        const endDate = new Date()
        endDate.setUTCHours(23, 59, 59, 999)
        url.searchParams.set('end_date', endDate.toISOString())

        const response = await fetch(url.toString(), {
          headers: {
            accept: 'application/json',
          },
        })

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`)
        }

        const result = await response.json()

        if (isCancelled) return // Check if the component is still mounted

        // Handle legacy format with counts array
        const counts =
          result.counts?.map((count: RawTrafficCount) => ({
            ...count,
            date: new Date(count.bucket * 1000),
          })) || []

        const summary = result.summary || {total: 0, unique: 0}

        const transformedData: TrafficData = {
          summary,
          counts,
        }

        setData(transformedData)
      } catch (err) {
        if (isCancelled) return

        const errorMessage = err instanceof Error ? err.message : 'Failed to fetch traffic data'
        setError(errorMessage)
      } finally {
        if (!isCancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchData()

    return () => {
      isCancelled = true // Cleanup function to prevent state updates if the component unmounts
    }
  }, [dataUrl, enabled, period])

  return {
    data,
    isLoading,
    error,
  }
}
