import {useReferringSites} from '../../hooks/use-referring-sites'
import {useRepoContext} from '../../hooks/use-repo-context'
import {GenericTrafficTable} from './GenericTrafficTable'
import type {TrafficDataItem} from '../TrafficDataTable'
import {useSearchParams} from '@github-ui/react-router'

export function ReferringSitesTable() {
  const {owner, repo} = useRepoContext()
  const fullDataUrl = `/${owner}/${repo}/graphs/traffic-new/referring-sites`

  const [searchParams, setSearchParams] = useSearchParams()
  const selectedReferrer = searchParams.get('referrer')

  const handleSelectReferrer = (referrer: string) => {
    const current = searchParams.get('referrer')
    if (current === referrer) {
      searchParams.delete('referrer')
    } else {
      searchParams.set('referrer', referrer)
    }
    setSearchParams(searchParams)
  }

  const {data, isLoading, error} = useReferringSites({
    dataUrl: fullDataUrl,
  })

  const transformedData =
    data?.map(
      (item, index) =>
        ({
          ...item,
          id: index.toString(),
        }) as TrafficDataItem,
    ) ?? null

  return (
    <GenericTrafficTable
      config={{
        title: 'Referring sites',
        emptyMessage: 'No referring sites data available for this period',
        ariaLabelledBy: 'referring-sites',
        firstColumnHeader: 'Site',
        linkType: 'site',
      }}
      trafficData={{data: transformedData, isLoading, error: error ?? null}}
      selectedReferrer={selectedReferrer}
      onSelectReferrer={handleSelectReferrer}
    />
  )
}

try{ ReferringSitesTable.displayName ||= 'ReferringSitesTable' } catch {}