import {useReferringPaths} from '../../hooks/use-referring-paths'
import {useRepoContext} from '../../hooks/use-repo-context'
import {GenericTrafficTable} from './GenericTrafficTable'
import type {TrafficDataItem} from '../TrafficDataTable'
import {useSearchParams} from '@github-ui/react-router'

export function ReferringPathsTable() {
  const {owner, repo} = useRepoContext()
  const fullDataUrl = `/${owner}/${repo}/graphs/traffic-new/referring-paths`

  const [searchParams, setSearchParams] = useSearchParams()
  const selectedReferrer = searchParams.get('referrer')

  const clearReferrer = () => {
    searchParams.delete('referrer')
    setSearchParams(searchParams)
  }

  const {data, isLoading, error} = useReferringPaths({
    dataUrl: fullDataUrl,
    referrer: selectedReferrer || '',
  })

  const transformedData =
    data?.map(
      (item, index) =>
        ({
          ...item,
          id: index.toString(),
        }) as TrafficDataItem,
    ) ?? null

  return (
    <GenericTrafficTable
      config={{
        title: 'Referring paths',
        emptyMessage: 'No referring paths data available for this period',
        ariaLabelledBy: 'referring-paths',
        firstColumnHeader: 'Path',
        linkType: 'path',
      }}
      trafficData={{data: transformedData, isLoading, error: error ?? null}}
      selectedReferrer={selectedReferrer}
      onClearReferrer={clearReferrer}
    />
  )
}

try{ ReferringPathsTable.displayName ||= 'ReferringPathsTable' } catch {}