import {Heading} from '@primer/react'
import {Table, DataTable, Blankslate} from '@primer/react/experimental'
import type {Column} from '@primer/react/experimental'
import {clsx} from 'clsx'
import {TrafficError} from './TrafficError'
import {LoadingState} from './TrafficLoading'
import styles from './Traffic.module.css'
import type {ReactNode} from 'react'

// Shared interface for traffic data items (replaces any[])
export interface TrafficDataItem {
  id: string
  site: string
  views: number
  uniqueVisitors: number
  referrerPathsAllowed?: boolean
  path?: string // For popular content, this stores the actual file path
  title?: string // For popular content, this stores the display title
}

interface TrafficDataTableProps {
  title: ReactNode
  data: TrafficDataItem[]
  isLoading: boolean
  error: string | null
  // Define a type for DataTable columns (customized to match Primer's DataTable expected structure)
  columns: Array<Column<TrafficDataItem>>
  emptyMessage: string
  ariaLabelledBy: string
  className?: string
}

export function TrafficDataTable({
  title,
  data,
  isLoading,
  error,
  columns,
  emptyMessage,
  ariaLabelledBy,
  className,
}: TrafficDataTableProps) {
  const sectionClasses = clsx(styles.bottomSectionColumn, 'pb-6', className)

  if (error) {
    return (
      <div className={sectionClasses}>
        <Heading as="h2" className="f3 text-semibold mb-1 color-fg-default">
          {title}
        </Heading>
        <TrafficError error={error} />
      </div>
    )
  }

  return (
    <div className={sectionClasses}>
      <Heading as="h2" className="f3 text-semibold mb-1 color-fg-default" data-hpc>
        {title}
      </Heading>

      <div className="mt-3">
        {isLoading ? (
          <LoadingState />
        ) : data && data.length > 0 ? (
          <Table.Container>
            <DataTable aria-labelledby={ariaLabelledBy} data={data} columns={columns} />
          </Table.Container>
        ) : (
          <Blankslate>
            <Blankslate.Description>{emptyMessage}</Blankslate.Description>
          </Blankslate>
        )}
      </div>
    </div>
  )
}

try{ TrafficDataTable.displayName ||= 'TrafficDataTable' } catch {}